'use client';
import { useState, useRef, useEffect } from 'react';
import { Menu } from 'lucide-react';
import Link from 'next/link';
import { motion, AnimatePresence, Variants } from 'framer-motion';
import Image from 'next/image';
import { PrimaryBtn , SecondaryBtn } from './LandBtn';


const dropdownVariants: Variants = {
  hidden: {
    opacity: 0,
    scale: 0.85,
    y: -8,
    transformOrigin: 'top right',
  },
  visible: {
    opacity: 1,
    scale: 1,
    y: 0,
    transition: {
      duration: 0.2,
      ease: [0.42, 0, 0.58, 1],
    },
  },
  exit: {
    opacity: 0,
    scale: 0.85,
    y: -8,
    transition: {
      duration: 0.15,
      ease: [0.4, 0, 1, 1],
    },
  },
};

const listItems = [
  {
    label: 'Home',
    href: '/',
  },
  {
    label: 'Courses',
    href: '/courses',
  },
];

function Navbar() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);



  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setIsMenuOpen(false);
      }
    }

    document.addEventListener('mousedown', handleClickOutside);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const toggleMenu = () => {
    if (menuRef.current && !menuRef.current.contains(document.activeElement)) {
      setIsMenuOpen(false);
    } else {
      setIsMenuOpen(!isMenuOpen);
    }
  };

  return (
    <>
      
<header className="fixed top-4 left-1/2 -translate-x-1/2 z-50 w-[90%] md:w-[70%] lg:w-[60%] mx-auto p-4  backdrop-blur-xl rounded-2xl shadow-sm text-foreground">
          <nav className="flex justify-between items-center">
            <Link href={'/'} className="flex items-center justify-center gap-2">
                <Image src="/zmaths-icon.svg" alt="Z-Maths Logo" width={40} height={40} className="rounded-full" />
            </Link>

            <ul className="md:flex gap-8 hidden items-center text-sm text-muted-foreground">
       
              <div className="flex gap-3 items-center">
                <>
                    
                    <Link
                      href={'/signup'}
                      onClick={() => setIsMenuOpen(false)}
                    >
                      <button className="px-5 py-2 bg-primary text-primary-foreground rounded-xl font-semibold hover:opacity-90 transition-all duration-300">
                        Sign Up
                      </button>
                    </Link>
                  </>

              </div>
            </ul>

            <button onClick={toggleMenu} className="md:hidden p-2 rounded-md text-foreground hover:bg-surface-muted transition-colors">
              <Menu className="text-current" />
            </button>
          </nav>

          <AnimatePresence>
            {isMenuOpen && (
              <motion.div
                key="dropdown"
                ref={menuRef}
                variants={dropdownVariants}
                initial="hidden"
                animate="visible"
                exit="exit"
                className="flex flex-col text-center gap-4 mt-4 p-4 rounded-xl bg-surface border border-border"
              >
                {listItems.map((item, i) => (
                  <Link
                    key={item.href}
                    href={item.href}
                    onClick={() => setIsMenuOpen(false)}
                    className="w-full px-5 py-3 bg-primary text-primary-foreground rounded-xl font-semibold hover:opacity-90 transition-opacity"
                  >
                    {item.label}
                  </Link>
                ))}
                <div className="flex flex-col gap-3 pt-3 border-t border-border">
                  <>
                    <Link href={'/login'} onClick={() => setIsMenuOpen(false)}>
                      <button className="w-full px-5 py-3 bg-primary text-primary-foreground rounded-xl font-semibold hover:opacity-90 transition-opacity">
                        Login
                      </button>
                    </Link>
                    <Link href={'/signup'} onClick={() => setIsMenuOpen(false)}>
                      <button className="w-full px-5 py-3 bg-primary text-primary-foreground rounded-xl font-semibold hover:opacity-90 transition-opacity">
                        Sign Up
                      </button>
                    </Link>
                  </>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </header>
    
    </>
  );
}

export default Navbar;